CREATE FUNCTION calculate_discount(amount DECIMAL, loyalty_years INT)
RETURNS DECIMAL
LANGUAGE plpgsql
AS $$
DECLARE
    discount_rate DECIMAL;
BEGIN
    IF loyalty_years > 10 THEN
        discount_rate = 0.20;
    ELSIF loyalty_years > 5 THEN
        discount_rate = 0.10;
    ELSE
        discount_rate = 0.05;
    END IF;

    RETURN amount * (1 - discount_rate);
END;
$$;

