RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    UPDATE product_summary
    SET 
        total_products = (SELECT COUNT(*) FROM products),
        average_price = (SELECT AVG(price) FROM products),
        total_stock = (SELECT SUM(stock) FROM products);
    RETURN NULL;
