-- Example deadlock scenario
-- Transaction 1
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- Transaction 2 (runs concurrently)
BEGIN;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
COMMIT;

-- Deadlock occurs when:
-- T1 locks account 1, waits for account 2
-- T2 locks account 2, waits for account 1

-- Fix: Consistent locking order
-- Always update account 1 before account 2
-- T1: UPDATE account 1, then account 2
-- T2: UPDATE account 1, then account 2

-- Detect deadlocks
-- PostgreSQL: Deadlocks logged
-- SET log_lock_waits = on;

-- Prevent deadlocks
-- 1. Access tables in consistent order
-- 2. Keep transactions short
-- 3. Use lower isolation levels
-- 4. Use advisory locks

