-- MySQL cursor example
DELIMITER //
CREATE PROCEDURE process_users()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE user_id INT;
    DECLARE user_name VARCHAR(100);
    DECLARE user_cursor CURSOR FOR SELECT id, name FROM users WHERE status = 'pending';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;

    OPEN user_cursor;

    read_loop: LOOP
        FETCH user_cursor INTO user_id, user_name;
        IF done THEN
            LEAVE read_loop;
        END IF;

        -- Process user
        INSERT INTO user_audit (user_id, action) VALUES (user_id, 'processed');
    END LOOP;

    CLOSE user_cursor;
END //
DELIMITER ;

-- When to use cursors
-- 1. Complex row-by-row processing
-- 2. Data migration with transformations
-- 3. Integration with external systems
-- 4. When set-based operations are impossible

-- When NOT to use cursors
-- 1. Simple UPDATE operations
-- 2. Data that can be processed in SET operations
-- 3. Large datasets (performance impact)
-- 4. Reporting (use set-based queries)

-- Alternative: Batch processing
-- Instead of cursor loop, process in batches
DO $$
DECLARE
    batch_size INT := 1000;
    processed INT := 0;
BEGIN
    LOOP
        WITH batch AS (
            SELECT id FROM users 
            WHERE status = 'pending' 
            LIMIT batch_size
        )
        UPDATE users 
        SET status = 'active' 
        WHERE id IN (SELECT id FROM batch);

        GET DIAGNOSTICS processed = ROW_COUNT;

        EXIT WHEN processed = 0;

        RAISE NOTICE 'Processed % rows', processed;
        COMMIT; -- Commit each batch
    END LOOP;
END $$;

