-- Zero-downtime migration strategies

-- 1. Add column (non-breaking)
-- Step 1: Add column with default
ALTER TABLE users ADD COLUMN new_column VARCHAR(100) DEFAULT 'default_value';
-- Step 2: Backfill gradually
UPDATE users SET new_column = old_column WHERE new_column IS NULL;
-- Step 3: Make NOT NULL if needed
ALTER TABLE users ALTER COLUMN new_column SET NOT NULL;

-- 2. Rename column (multi-step)
-- Step 1: Add new column
ALTER TABLE users ADD COLUMN new_name VARCHAR(100);
-- Step 2: Dual-write (application writes to both)
-- INSERT INTO users (name, new_name) VALUES ('John', 'John');
-- Step 3: Backfill
UPDATE users SET new_name = name WHERE new_name IS NULL;
-- Step 4: Switch reads to new column
-- Application reads from new_name
-- Step 5: Drop old column
ALTER TABLE users DROP COLUMN name;
-- Step 6: Rename new column
ALTER TABLE users RENAME COLUMN new_name TO name;

-- 3. Split table (normalization)
-- Step 1: Create new table
CREATE TABLE user_profiles (user_id INT PRIMARY KEY, bio TEXT);
-- Step 2: Dual-write (application writes to both)
-- Step 3: Backfill
INSERT INTO user_profiles (user_id, bio)
SELECT id, bio FROM users WHERE bio IS NOT NULL;
-- Step 4: Remove column from original
ALTER TABLE users DROP COLUMN bio;

-- 4. Add index (concurrently)
CREATE INDEX CONCURRENTLY idx_users_email ON users(email);
-- Wait for index to complete
-- Verify index

-- 5. Add foreign key
-- Step 1: Add column without constraint
ALTER TABLE orders ADD COLUMN user_id INT;
-- Step 2: Backfill data
UPDATE orders SET user_id = (SELECT id FROM users WHERE users.name = orders.name);
-- Step 3: Add constraint (validate)
ALTER TABLE orders ADD CONSTRAINT fk_user FOREIGN KEY (user_id) REFERENCES users(id) NOT VALID;
-- Step 4: Validate constraint
ALTER TABLE orders VALIDATE CONSTRAINT fk_user;

-- 6. Change data type (with casting)
-- Step 1: Add new column with correct type
ALTER TABLE users ADD COLUMN new_id UUID;
-- Step 2: Convert data
UPDATE users SET new_id = id::TEXT::UUID;
-- Step 3: Rename
ALTER TABLE users RENAME COLUMN id TO old_id;
ALTER TABLE users RENAME COLUMN new_id TO id;
ALTER TABLE users ALTER COLUMN id SET NOT NULL;
ALTER TABLE users ADD PRIMARY KEY (id);

-- 7. Partitioning existing table
-- Step 1: Create new partitioned table
CREATE TABLE orders_new (LIKE orders INCLUDING ALL) PARTITION BY RANGE (order_date);
-- Step 2: Create partitions
CREATE TABLE orders_2024 PARTITION OF orders_new FOR VALUES FROM ('2024-01-01') TO ('2025-01-01');
-- Step 3: Copy data (batch)
INSERT INTO orders_new SELECT * FROM orders WHERE order_date >= '2024-01-01';
-- Step 4: Switch tables
ALTER TABLE orders RENAME TO orders_old;
ALTER TABLE orders_new RENAME TO orders;
-- Step 5: Clean up
DROP TABLE orders_old;

