-- Anti-pattern 1: SELECT *
-- Bad
SELECT * FROM users;

-- Good
SELECT id, name, email FROM users;

-- Anti-pattern 2: EAV (Entity-Attribute-Value)
-- Bad
CREATE TABLE product_attributes (
    product_id INT,
    attribute_name TEXT,
    attribute_value TEXT
);

-- Good
CREATE TABLE products (
    id INT PRIMARY KEY,
    name TEXT,
    color TEXT,
    size TEXT,
    weight DECIMAL
);

-- Anti-pattern 3: CSV in column
-- Bad
CREATE TABLE products (
    id INT PRIMARY KEY,
    name TEXT,
    tags TEXT -- 'electronics,portable,new'
);

-- Good (many-to-many)
CREATE TABLE tags (
    id INT PRIMARY KEY,
    name TEXT
);

CREATE TABLE product_tags (
    product_id INT,
    tag_id INT
);

-- Anti-pattern 4: Polymorphic associations
-- Bad
CREATE TABLE comments (
    id INT PRIMARY KEY,
    commentable_type TEXT, -- 'Post' or 'Photo'
    commentable_id INT
);

-- Good
CREATE TABLE comments (
    id INT PRIMARY KEY,
    post_id INT,
    photo_id INT,
    CHECK (num_nonnulls(post_id, photo_id) = 1)
);

-- Anti-pattern 5: Magic numbers
-- Bad
SELECT * FROM users WHERE status = 1; -- What is 1?

-- Good
CREATE TYPE user_status AS ENUM ('active', 'inactive', 'pending');
SELECT * FROM users WHERE status = 'active';

-- Anti-pattern 6: Not using schemas
-- Create separate schemas for different modules
CREATE SCHEMA sales;
CREATE SCHEMA inventory;

-- Anti-pattern 7: Over-indexing
-- Too many indexes slow down writes
-- Remove unused indexes
SELECT * FROM pg_stat_user_indexes WHERE idx_scan = 0;

-- Anti-pattern 8: Not using transactions
-- Bad (partial failures)
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;

-- Good
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

-- Anti-pattern 9: Generic columns
-- Bad
CREATE TABLE settings (
    id INT PRIMARY KEY,
    setting_name TEXT,
    setting_value TEXT
);

-- Good
CREATE TABLE user_settings (
    user_id INT,
    theme TEXT,
    notifications BOOLEAN,
    language TEXT
